	/** Composer-originated steer: consumes the composer's attachments and quote
	*  chips so they ride the steer as one unit (the server re-fetches + encodes
	*  files and merges quotes at the injection boundary). Both are taken only
	*  after the guards pass: with `canSteer` true, `submitSteer` cannot
	*  refuse, so the drained context can never be stranded. */
	const steerFromComposer = useCallback((text, preempt = false) => {
		const trimmed = text.trim();
		if (composerDisabledRef.current || trimmed.length === 0 || filesLoading || !canSteer) return false;
		/** A live steer cannot change the provider request already in flight.
		* Preserve a staged reasoning choice as a full queued turn. */
		if (pendingReasoningOverride != null) {
			enqueue(trimmed, {
				files: takeComposerFiles(),
				...takeComposerContext()
			});
			takeComposerDraft();
			return true;
		}
		const consumed = submitSteer(trimmed, takeComposerFiles(), takeComposerQuotes(), { preempt });
		if (consumed) takeComposerDraft();
		return consumed;
	}, [
		composerDisabledRef,
		filesLoading,
		canSteer,
		pendingReasoningOverride,
		enqueue,
		takeComposerFiles,
		takeComposerContext,
		takeComposerQuotes,
		takeComposerDraft,
		submitSteer
	]);
	/** Composer-originated queue: carries the composer's attachments, quote
	*  chips, and manual skill picks as one unit. */
	const queueFromComposer = useCallback((text) => {
		const trimmed = text.trim();
		if (composerDisabledRef.current || trimmed.length === 0 || filesLoading) return false;
		enqueue(trimmed, {
			files: takeComposerFiles(),
			...takeComposerContext()
		});
		takeComposerDraft();
		return true;
	}, [
		composerDisabledRef,
		filesLoading,
		enqueue,
		takeComposerFiles,
		takeComposerContext,
		takeComposerDraft
	]);
