	const interruptAndSend = useCallback((text) => {
		const trimmed = text.trim();
		if (composerDisabledRef.current || trimmed.length === 0 || filesLoading || !canControlGeneration) return false;
		enqueue(trimmed, {
			front: true,
			files: takeComposerFiles(),
			...takeComposerContext()
		});
		takeComposerDraft();
		armDrainAfterAbort();
		stopGenerating();
		return true;
	}, [
		composerDisabledRef,
		filesLoading,
		canControlGeneration,
		enqueue,
		takeComposerFiles,
		takeComposerContext,
		takeComposerDraft,
		armDrainAfterAbort,
		stopGenerating
	]);
	/** Preempt the active step and continue the same response with the message. */
	const interruptSteer = useCallback((text) => {
		const trimmed = text.trim();
		if (composerDisabledRef.current || trimmed.length === 0 || filesLoading || pausedOnApproval || !canControlGeneration || !hasRealConvoId) return false;
		if (pendingReasoningOverride != null) return false;
		const consumed = submitSteer(trimmed, takeComposerFiles(), takeComposerQuotes(), { preempt: true });
		if (consumed) takeComposerDraft();
		return consumed;
	}, [
		composerDisabledRef,
		filesLoading,
		pausedOnApproval,
		canControlGeneration,
		hasRealConvoId,
		pendingReasoningOverride,
		takeComposerFiles,
		takeComposerQuotes,
		takeComposerDraft,
		submitSteer
	]);
